import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias
);
"""

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int IC, int IH, int IW, int ID,
    int OC, int KH, int KW, int KD,
    int OH, int OW, int OD,
    int stride, int pad, int dilation,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * OC * OH * OW * OD;
    if (idx >= total) return;

    int tmp = idx;
    int b = tmp / (OC * OH * OW * OD);
    tmp %= (OC * OH * OW * OD);
    int oc = tmp / (OH * OW * OD);
    tmp %= (OH * OW * OD);
    int oh = tmp / (OW * OD);
    tmp %= (OW * OD);
    int ow = tmp / OD;
    int od = tmp % OD;

    float value = 0.0f;

    for (int ic = 0; ic < IC; ic++) {
        for (int kh = 0; kh < KH; kh++) {
            for (int kw = 0; kw < KW; kw++) {
                for (int kd = 0; kd < KD; kd++) {
                    int in_h = oh * stride - pad + kh * dilation;
                    int in_w = ow * stride - pad + kw * dilation;
                    int in_d = od * stride - pad + kd * dilation;
                    if (in_h >= 0 && in_h < IH && in_w >= 0 && in_w < IW && in_d >= 0 && in_d < ID) {
                        int in_idx = b * (IC * IH * IW * ID)
                                   + ic * (IH * IW * ID)
                                   + in_h * (IW * ID)
                                   + in_w * (ID)
                                   + in_d;

                        int wt_idx = oc * (IC * KH * KW * KD)
                                   + ic * (KH * KW * KD)
                                   + kh * (KW * KD)
                                   + kw * KD
                                   + kd;

                        value += input[in_idx] * weight[wt_idx];
                    }
                }
            }
        }
    }

    if (has_bias) {
        value += bias[oc];
    }

    int out_idx = b * (OC * OH * OW * OD)
                + oc * (OH * OW * OD)
                + oh * (OW * OD)
                + ow * OD
                + od;

    output[out_idx] = value;
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    auto B = input.size(0);
    auto IC = input.size(1);
    auto IH = input.size(2);
    auto IW = input.size(3);
    auto ID = input.size(4);

    auto OC = weight.size(0);
    auto KH = weight.size(2);
    auto KW = weight.size(3);
    auto KD = weight.size(4);

    int OH = (IH + 2*padding - dilation*(KH - 1) - 1) / stride + 1;
    int OW = (IW + 2*padding - dilation*(KW - 1) - 1) / stride + 1;
    int OD = (ID + 2*padding - dilation*(KD - 1) - 1) / stride + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({B, OC, OH, OW, OD}, options);

    int total = B * OC * OH * OW * OD;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    conv3d_forward_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        B, (int)IC, (int)IH, (int)IW, (int)ID,
        (int)OC, (int)KH, (int)KW, (int)KD,
        (int)OH, (int)OW, (int)OD,
        stride, padding, dilation,
        has_bias
    );

    return output;
}
"""

conv3d = load_inline(
    name="custom_conv3d_extension",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    extra_cflags=[],
    extra_ldflags=[],
    functions=["conv3d_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        self.weight = nn.Parameter(torch.randn(
            out_channels,
            in_channels,
            kernel_size,
            kernel_size,
            1
        ))
        if self.has_bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv3d.conv3d_forward_cuda(
            x,
            self.weight,
            self.bias if self.has_bias else torch.tensor([], device=x.device, dtype=x.dtype),
            self.stride,
            self.padding,
            self.dilation,
            self.has_bias
        )
